#!/usr/bin/env node
'use strict';
// #37 (Casey 2026-11-21): a scan the phone starts and the desktop runs, in
// main, phone locked or not. The phone's filters come out exactly as its own
// applyFilters (the shared vectors, generated by the phone and run by both
// apps), the desktop's own exclusions on top, and the run's start, step and
// end rules from the ask (echocat docs/desktop-asks/2026-11-21-scan-on-the-desktop.md).
// Run: node test/scan-run-test.js

const assert = require('assert');
const fs = require('fs');
const path = require('path');
const S = require('../lib/scan-run');
const V = require('./fixtures/scan/scan-filter-vectors.json');

let pass = 0, fail = 0;
function test(name, fn) {
  try { fn(); pass++; console.log('  ok  ' + name); }
  catch (e) { fail++; console.log('  FAIL ' + name + '\n       ' + (e.stack || e.message)); }
}

console.log('Scan from the phone, run on the desktop (#37)');

for (const c of V.cases) {
  test('shared vector: ' + c.name, () => {
    assert.deepStrictEqual(S.scanList(V.spots, c.criteria, {}).map((s) => s.callsign), c.expect);
  });
}

test('the traps the ask names', () => {
  assert.strictEqual(S.modeCategory({ mode: '', frequency: '14230' }), 'SSTV', 'blank mode on a calling frequency');
  assert.strictEqual(S.modeCategory({ mode: 'USB', frequency: '14231.5' }), 'SSB', 'not within 1 kHz');
  assert.strictEqual(S.regionOf({ continent: '', locationDesc: 'CN-1234' }), 'AS', 'CN is in AS and AF: AS first');
  assert.strictEqual(S.regionOf({ locationDesc: 'Somewhere' }), 'EU');
  assert.strictEqual(S.regionOf({}), '');
  const d = S.sortSpots([{ callsign: 'A', distance: '0' }, { callsign: 'B', distance: '5' }, { callsign: 'C', distance: '' }], 'dist').map((s) => s.callsign);
  assert.deepStrictEqual(d, ['B', 'A', 'C'], 'distance 0 sorts as Infinity; ties keep incoming order');
});

test('the desktop exclusions apply on top: mute rules, hidden, skipped, worked today (always)', () => {
  const spots = V.spots;
  const ctx = {
    muteRules: [{ continent: 'AS', band: '40m' }],                 // JA4DDD
    isHidden: (s) => s.callsign === 'G3CCC',
    isSkipped: (s) => s.callsign === 'K8HHH',
    isWorkedToday: (s) => s.callsign === 'W2BBB',
  };
  const got = S.scanList(spots, { sort: 'freq' }, ctx).map((s) => s.callsign);
  assert.deepStrictEqual(got, ['K1AAA', 'VK5EEE', 'N6FFF', 'PY7GGG']);
  // hideWorked false still removes worked spots, as the phone's scan does
  assert.ok(!S.scanList(spots, { hideWorked: false }, ctx).some((s) => s.callsign === 'W2BBB'));
});

test('worked today is the desktop table\'s rule: band, mode (USB/LSB as SSB) and the park when the spot names one', () => {
  const today = '20261121';
  const e = [{ date: today, ref: 'US-0002', band: '20M', mode: 'SSB' }];
  assert.strictEqual(S.workedToday({ callsign: 'W2BBB', reference: 'US-0002', band: '20m', mode: 'USB' }, e, today), true);
  assert.strictEqual(S.workedToday({ callsign: 'W2BBB', reference: 'US-0999', band: '20m', mode: 'USB' }, e, today), false, 'a new park');
  assert.strictEqual(S.workedToday({ callsign: 'W2BBB', reference: 'US-0002', band: '40m', mode: 'USB' }, e, today), false, 'another band');
  assert.strictEqual(S.workedToday({ callsign: 'W2BBB', reference: 'US-0002', band: '20m', mode: 'USB' }, [{ ...e[0], date: '20261120' }], today), false, 'yesterday');
});

test('hidden by main\'s one list: whole call, whole kHz or band, null = forever, expired = not hidden', () => {
  const now = 1000;
  assert.strictEqual(S.hiddenBy({ K1AAA: { '*': null } }, { callsign: 'k1aaa', frequency: '14062.5' }, now), true);
  assert.strictEqual(S.hiddenBy({ K1AAA: { 14063: 5000 } }, { callsign: 'K1AAA', frequency: '14062.5' }, now), true);
  assert.strictEqual(S.hiddenBy({ K1AAA: { 'band:20m': 500 } }, { callsign: 'K1AAA', frequency: '14062.5', band: '20m' }, now), false, 'expired');
});

test('start: within 0.05 kHz of fromFreqKhz, else within 0.2 kHz of the dial, else the first', () => {
  const list = S.sortSpots(V.spots, 'freq');
  assert.strictEqual(list[S.startIndex(list, 14080.04, 0)].callsign, 'K8HHH');
  assert.strictEqual(list[S.startIndex(list, 0, 14229.85)].callsign, 'N6FFF');
  assert.strictEqual(S.startIndex(list, 1, 2), 0);
});

test('step: one dwell per frequency string, wrapping', () => {
  const list = [{ callsign: 'A', frequency: '7030' }, { callsign: 'B', frequency: '7030' }, { callsign: 'C', frequency: '7040' }];
  assert.strictEqual(S.nextIndex(list, '7030'), 2);
  assert.strictEqual(S.nextIndex(list, '7040'), 0);
  assert.strictEqual(S.nextIndex(list, '9999'), 0);
});

function harness(spots, opts = {}) {
  let t = 0;
  const timers = [];
  const tuned = [], states = [], logs = [];
  let tx = false;
  const run = S.createScanRun({
    getSpots: () => (typeof spots === 'function' ? spots() : spots),
    ctx: () => ({}),
    tune: (sp) => { if (opts.cannotTune) return false; tuned.push(sp.callsign); return true; },
    dialKhz: () => opts.dial || 0,
    txActive: () => tx,
    onState: (on, why) => states.push([on, why]),
    log: (l) => logs.push(l),
    now: () => t,
    setTimer: (fn, ms) => { timers.push({ fn, at: t + ms }); return timers.length; },
    clearTimer: (h) => { if (timers[h - 1]) timers[h - 1].fn = null; },
  });
  const advance = (ms) => { t += ms; for (const tm of timers.slice()) if (tm.fn && tm.at <= t) { const f = tm.fn; tm.fn = null; f(); } };
  return { run, tuned, states, logs, advance, setTx: (v) => { tx = v; }, now: () => t };
}

test('a run walks the list at dwellSec, wraps, and tells every phone it is scanning', () => {
  const h = harness(V.spots);
  h.run.start({ filters: { bands: ['20m'], sort: 'freq' }, dwellSec: 5, fromFreqKhz: 14074 });
  assert.deepStrictEqual(h.states[0], [true, 'start']);
  assert.deepStrictEqual(h.tuned, ['VK5EEE']);
  h.advance(5000); h.advance(5000); h.advance(5000); h.advance(5000);
  assert.deepStrictEqual(h.tuned, ['VK5EEE', 'K8HHH', 'N6FFF', 'W2BBB', 'K1AAA'], 'wraps to the first');
  assert.strictEqual(h.run.scanning, true);
});

test('the run ends on an empty list, a transmit, a hand tune after the settle, and stop; never on a phone leaving', () => {
  let list = V.spots;
  const h = harness(() => list);
  h.run.start({ filters: { sort: 'freq' }, dwellSec: 7 });
  list = [];
  h.advance(7000);
  assert.strictEqual(h.run.scanning, false);
  assert.deepStrictEqual(h.states[h.states.length - 1], [false, 'empty']);

  const t2 = harness(V.spots);
  t2.run.start({ filters: { sort: 'freq' } });
  t2.run.noteTransmit();
  assert.deepStrictEqual(t2.states[t2.states.length - 1], [false, 'transmit']);

  const t3 = harness(V.spots);
  t3.run.start({ filters: { sort: 'freq' } });          // first spot: JA4DDD 7032
  t3.run.noteDial(14000);                                // inside the settle: nothing
  assert.strictEqual(t3.run.scanning, true);
  t3.advance(3000);
  t3.run.noteDial(7029);                                 // an offset under 4 kHz (an FT8 dial): still ours
  assert.strictEqual(t3.run.scanning, true);
  t3.run.noteDial(7250);                                 // moved by hand
  assert.deepStrictEqual(t3.states[t3.states.length - 1], [false, 'manual-qsy']);

  const t4 = harness(V.spots);
  t4.run.start({ filters: {} });
  t4.setTx(true);
  t4.advance(7000);
  assert.deepStrictEqual(t4.states[t4.states.length - 1], [false, 'transmit'], 'a transmit seen at the next step');

  const t5 = harness(V.spots);
  t5.run.start({ filters: {} });
  assert.strictEqual(t5.run.stop('stop'), true);
  assert.strictEqual(t5.run.stop('stop'), false);
});

test('a radio that cannot be tuned ends the run at once', () => {
  const h = harness(V.spots, { cannotTune: true });
  assert.strictEqual(h.run.start({ filters: {} }), false);
  assert.deepStrictEqual(h.states[h.states.length - 1], [false, 'not-tunable']);
});

test('wire and glue: capability, parsed fields, main loop, every end hook', () => {
  const read = (f) => fs.readFileSync(path.join(__dirname, '..', f), 'utf8');
  const rs = read('lib/remote-server.js');
  assert.ok(rs.includes("'scan-remote-v1',"), 'hello capability');
  assert.ok(/this\.emit\('scan-control', \{[\s\S]{0,400}filters:[\s\S]{0,200}dwellSec:[\s\S]{0,200}fromFreqKhz:/.test(rs), 'the start fields reach main');
  assert.ok(/'scan-control': \{ dir: Dir\.BOTH, feature: 'rig', fields: \{ action: f\.string, filters: f\.optObject, dwellSec: f\.optNumber, fromFreqKhz: f\.optNumber \} \}/.test(read('lib/echocat-protocol.js')));
  const main = read('main.js');
  assert.ok(/if \(action === 'start' && filters && !isRemoteMode\(\)\) \{[\s\S]{0,400}phoneScanRun\(\)\.start\(\{ filters, dwellSec, fromFreqKhz(, by: [^}]+)? \}\)/.test(main), 'a start with filters runs in main');
  assert.ok(/_phoneScanRun\.noteDial\(hz \/ 1000\)/.test(main), 'hand tune ends it (the one frequency sink)');
  assert.ok(/if \(state && _phoneScanRun && _phoneScanRun\.scanning\) _phoneScanRun\.noteTransmit\(\)/.test(main), 'every key-down ends it');
  assert.ok(/_phoneScanRun\.stop\('desktop-scan'\)/.test(main), 'the desktop Scan button takes over');
  assert.ok(/remoteServer\.sendToClient\(\{ type: 'scan-state', scanning: scanStateNow\(\) \}\)/.test(main), 'scan-state on change and at connect');
  assert.ok(/setTimer: \(fn, ms\) => setTimeout\(fn, ms\)/.test(main), 'a main-process timer, not the renderer');
});

// #961: a desktop-run scan a Guest Pass phone started stops when the pass
// ends (every reason) or the owner takes the radio back; the owner's never.
const PASS_END_REASONS = ['expired', 'revoked', 'owner_override', 'disconnected', 'superseded', 'left', 'paused'];

test('#961: a guest-started scan stops on every pass end reason and on pause, and nothing is tuned', () => {
  for (const reason of PASS_END_REASONS) {
    const h = harness(V.spots);
    h.run.start({ filters: { sort: 'freq' }, by: 'guest' });
    assert.strictEqual(h.run.startedBy, 'guest');
    const tunedBefore = h.tuned.length;
    const why = S.guestScanEndWhy(reason);
    assert.strictEqual(why, reason === 'paused' ? 'pass-paused' : 'pass-ended', reason);
    assert.strictEqual(h.run.stopGuestRun(why), true, reason + ' stops it');
    assert.strictEqual(h.run.scanning, false, reason);
    assert.deepStrictEqual(h.states[h.states.length - 1], [false, why], reason + ': every phone told scanning off');
    assert.ok(h.logs[h.logs.length - 1].includes(S.END_WORDS[why]), reason + ': one log line says why');
    h.advance(60000);
    assert.strictEqual(h.tuned.length, tunedBefore, reason + ': no further tune, the radio stays where it is');
  }
  assert.strictEqual(S.guestScanEndWhy('resumed'), null, 'resume stops nothing');
});

test('#961: an owner-started scan is never stopped by a pass end or pause', () => {
  for (const reason of PASS_END_REASONS) {
    for (const by of ['owner', undefined]) {
      const h = harness(V.spots);
      h.run.start({ filters: { sort: 'freq' }, by });
      assert.strictEqual(h.run.startedBy, 'owner');
      assert.strictEqual(h.run.stopGuestRun(S.guestScanEndWhy(reason)), false, reason);
      assert.strictEqual(h.run.scanning, true, reason + ': the owner scan runs on');
    }
  }
  const h = harness(V.spots);
  h.run.start({ filters: {}, by: 'guest' });
  h.run.start({ filters: {}, by: 'owner' }); // the owner restarts it: now the owner's
  assert.strictEqual(h.run.stopGuestRun('pass-ended'), false);
  assert.strictEqual(h.run.scanning, true);
  const idle = harness(V.spots);
  assert.strictEqual(idle.run.stopGuestRun('pass-ended'), false, 'no run: nothing to stop');
  assert.strictEqual(idle.run.startedBy, '');
});

test('#961 wiring: the guest flag reaches main, the start records it, every pass end path stops the guest scan', () => {
  const read = (f) => fs.readFileSync(path.join(__dirname, '..', f), 'utf8');
  const rs = read('lib/remote-server.js');
  const c = rs.indexOf("case 'scan-control':");
  assert.ok(/guest: !!ws\._passSession/.test(rs.slice(c, c + 900)), 'scan-control carries whether a Guest Pass phone sent it');
  const main = read('main.js');
  assert.ok(/remoteServer\.on\('scan-control', \(\{ action, filters, dwellSec, fromFreqKhz, guest \}\)/.test(main), 'main reads the guest flag');
  assert.ok(/phoneScanRun\(\)\.start\(\{ filters, dwellSec, fromFreqKhz, by: guest \? 'guest' : 'owner' \}\)/.test(main), 'the start records who started it');
  const i = main.indexOf('function passLeaseStopTransmitters(');
  const body = main.slice(i, main.indexOf('\n}\n', i));
  assert.ok(/step\('scan', \(\) => \{ const why = ScanRun\.guestScanEndWhy\(reason\); return !!\(why && _phoneScanRun && _phoneScanRun\.stopGuestRun\(why\)\); \}\)/.test(body), 'the lease end stops the guest scan, the owner scan never');
  assert.ok(/const stopped = info\.wasPaused \? \[\] : passLeaseStopTransmitters\(info\.reason\)/.test(main), 'ended (expired, revoked, left, disconnected, ...) runs it');
  assert.ok(/const stopped = passLeaseStopTransmitters\('paused'\);\s*passEnforcement\.pause\(\)/.test(main), 'the owner taking the radio back runs it');
});

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
